import { test, expect } from '@playwright/test';

test.describe('Landing footer and about links', () => {
  test('Founders LinkedIn links on about page are real or removed @desktop @prod-safe (#1afa56)', async ({ page }) => {
    // 1. Open /about as guest
    await page.goto('/about');

    // 2. Scroll to «נעים להכיר!» (founders block)
    const heading = page.getByRole('heading', { name: 'נעים להכיר!' });
    await heading.scrollIntoViewIfNeeded();
    await expect(heading).toBeVisible();

    // 3. Look for the founders' LinkedIn links: absent, or a real linkedin.com URL
    for (const name of ['בת אל הוד ב-LinkedIn', 'חלי קרן ב-LinkedIn']) {
      const link = page.getByRole('link', { name });
      const count = await link.count();
      for (let i = 0; i < count; i++) {
        const href = await link.nth(i).getAttribute('href');
        expect(href, name).not.toBe('#');
        expect(href, name).toMatch(/^https:\/\/www\.linkedin\.com\//);
      }
    }

    // No link in the main content has href="#"
    const hashLinks = await page.locator('main a').evaluateAll((els) =>
      els.map((a) => a.getAttribute('href') ?? '').filter((h) => h === '#' || h.endsWith('/#')),
    );
    expect(hashLinks).toHaveLength(0);
  });
});
